+public final class PolynomialHashCalculator implements HashCalculator {
+    private final int radix;
+    private final int modulus;
+
+    public PolynomialHashCalculator(int radix, int modulus) {
+        this.radix = radix;
+        this.modulus = modulus;
+    }
